pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        uint256 value = bound(amount, 0, 100 ether);

        vm.deal(actor, value);
        bool ok;
        vm.prank(actor);
        (bool success, ) = address(c).call{value: value}("");
        ok = success;

        assertTrue(ok == (value == 10 ether));
    }
}
